# Single-process ai_agent + wait WiFi + ask (COM3)
param([string]$ComPort = "COM3")
$ErrorActionPreference = "Stop"
$pass = 0
$fail = 0
$log = Join-Path (Split-Path -Parent $MyInvocation.MyCommand.Path) "serial_ask_verbose.log"
$lines = New-Object System.Collections.Generic.List[string]

function Log([string]$s) {
  Write-Output $s
  $lines.Add($s) | Out-Null
}

$cubeCandidates = @(
  "D:\Develop\STM32CubeCLT_1.21.0\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe",
  "D:\Develop\STM32CubeCLT\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe"
)
foreach ($c in $cubeCandidates) {
  if (Test-Path -LiteralPath $c) {
    & $c -c port=SWD mode=UR -rst | Out-Null
    Start-Sleep -Seconds 2
    break
  }
}

function Read-Until([System.IO.Ports.SerialPort]$p, [int]$sec) {
  $b = ""
  $dl = (Get-Date).AddSeconds($sec)
  while ((Get-Date) -lt $dl) {
    if ($p.BytesToRead -gt 0) { $b += $p.ReadExisting() }
    Start-Sleep -Milliseconds 100
  }
  return $b
}

function Cmd([System.IO.Ports.SerialPort]$p, [string]$c, [int]$sec) {
  $p.DiscardInBuffer()
  $p.Write("$c`r")
  Start-Sleep -Milliseconds 500
  $b = Read-Until $p $sec
  Log "`n=== $c ===`n$b"
  return $b
}

$port = New-Object System.IO.Ports.SerialPort $ComPort, 115200
$port.ReadTimeout = 8000
$port.DtrEnable = $true
$port.RtsEnable = $true
$port.Open()
Start-Sleep 1
Read-Until $port 30 | Out-Null

$a = Cmd $port "ai_agent" 90
if ($a -match "vela>") { Log "[PASS] vela prompt"; $pass++ } else { Log "[FAIL] vela prompt"; $fail++ }

$netUp = $false
for ($i = 0; $i -lt 24; $i++) {
  $ns = Cmd $port "net_status" 10
  if ($ns -match "connected|UP|yes|192\.") {
    Log "[PASS] network up (try $i)"
    $pass++
    $netUp = $true
    break
  }
  Start-Sleep 5
}
if (-not $netUp) { Log "[WARN] network not confirmed up" }

$nt = Cmd $port "net_test" 90
if ($nt -match "HTTP Status: 200") { Log "[PASS] net_test"; $pass++ } else { Log "[FAIL] net_test"; $fail++ }

$h = Cmd $port "ask hello" 90
if ($h -match "\[Agent\]:") { Log "[PASS] ask hello"; $pass++ } else { Log "[FAIL] ask hello"; $fail++ }

$z = Cmd $port "ask 你好" 90
if ($z -match "\[Agent\]:") { Log "[PASS] ask 你好"; $pass++ } else { Log "[FAIL] ask 你好"; $fail++ }

Cmd $port "quit" 15 | Out-Null
$port.Close()
Log "`n[serial_ask_test] pass=$pass fail=$fail"
$lines | Set-Content -LiteralPath $log -Encoding UTF8
if ($fail -gt 0) { exit 1 }

