# Robust COM3 ask test — always Close() in finally
param([string]$ComPort = "COM3")
$ErrorActionPreference = "Stop"
$pass = 0
$fail = 0

$cli = "D:\Develop\STM32CubeCLT_1.21.0\STM32CubeProgrammer\bin\STM32_Programmer_CLI.exe"
if (Test-Path $cli) {
  & $cli -c port=SWD mode=UR -rst | Out-Null
  Start-Sleep 3
}

$port = $null
try {
  $port = New-Object System.IO.Ports.SerialPort $ComPort, 115200
  $port.ReadTimeout = 8000
  $port.DtrEnable = $true
  $port.RtsEnable = $true
  $port.Open()

  function Read-Until([int]$sec, [string]$pat = "") {
    $b = ""
    $dl = (Get-Date).AddSeconds($sec)
    while ((Get-Date) -lt $dl) {
      if ($port.BytesToRead -gt 0) { $b += $port.ReadExisting() }
      if ($pat -ne "" -and $b -match $pat) { break }
      Start-Sleep -Milliseconds 100
    }
    return $b
  }
  function Cmd([string]$c, [int]$sec, [string]$pat = "") {
    $port.DiscardInBuffer()
    $port.Write("$c`r")
    Start-Sleep -Milliseconds 500
    return Read-Until $sec $pat
  }

  $boot = Read-Until 45 "nsh>"
  Write-Output "boot nsh=$($boot -match 'nsh>')"

  $ag = Cmd "ai_agent" 50 "vela>"
  if ($ag -match "panic|dump_assert") {
    Write-Output "[FAIL] ai_agent panic"
    $fail++
  } elseif ($ag -match "vela>") {
    Write-Output "[PASS] vela (lazy=$($ag -match 'lazy'))"
    $pass++
  } else {
    Write-Output "[FAIL] no vela>"
    $fail++
  }

  Start-Sleep 8
  $nt = Cmd "net_test" 90 "HTTP Status: 200"
  if ($nt -match "HTTP Status: 200") {
    Write-Output "[PASS] net_test"
    $pass++
  } else {
    Write-Output "[FAIL] net_test"
    $fail++
  }

  $ask = Cmd "ask hello" 120 "\[Agent\]:|deferred|panic|dump_assert"
  Write-Output "=== ask hello (len=$($ask.Length)) ==="
  Write-Output ($ask.Substring(0, [Math]::Min(2000, $ask.Length)))
  if ($ask -match "panic|dump_assert") {
    Write-Output "[FAIL] ask panic"
    $fail++
  } elseif ($ask -match "\[Agent\]:") {
    Write-Output "[PASS] ask hello"
    $pass++
  } elseif ($ask -match "deferred") {
    Write-Output "[WARN] deferred, retry..."
    Start-Sleep 8
    $ask2 = Cmd "ask hello" 120 "\[Agent\]:|panic"
    if ($ask2 -match "\[Agent\]:") {
      Write-Output "[PASS] ask hello (retry)"
      $pass++
    } else {
      Write-Output "[FAIL] ask after defer"
      $fail++
    }
  } else {
    Write-Output "[FAIL] no [Agent]:"
    $fail++
  }

  Cmd "quit" 10 "nsh>" | Out-Null
  Write-Output "`n[result] pass=$pass fail=$fail"
  if ($fail -gt 0) { exit 1 }
  exit 0
}
finally {
  if ($port -ne $null -and $port.IsOpen) {
    $port.Close()
    Write-Output "[cleanup] COM3 closed"
  }
}

