$ask = Cmd "ask hello" 150 "\[Agent\]:|panic|dump_assert|agent_loop started"
Write-Output "=== ask hello (len=$($ask.Length)) ==="
Write-Output ($ask.Substring(0, [Math]::Min(2500, $ask.Length)))
if ($ask -match "panic|dump_assert") {
  Write-Output "[FAIL] ask panic"
  $fail++
} elseif ($ask -match "\[Agent\]:") {
  Write-Output "[PASS] ask hello"
  $pass++
} else {
  # Background start may need a second ask / longer wait
  Write-Output "[INFO] waiting more for [Agent]..."
  Start-Sleep 5
  $more = Read-Until 90 "\[Agent\]:|panic"
  Write-Output ($more.Substring(0, [Math]::Min(1500, $more.Length)))
  if ($more -match "\[Agent\]:") {
    Write-Output "[PASS] ask hello (delayed)"
    $pass++
  } elseif ($more -match "panic") {
    Write-Output "[FAIL] delayed panic"
    $fail++
  } else {
    Write-Output "[FAIL] no [Agent]:"
    $fail++
  }
}

